# Annuaire : Institut des Futurs souhaitables et formations
# Fiche publique, logo officiel et nouvelle catégorie, sans données WhatsApp.
from pathlib import Path, PurePosixPath
import json, hashlib, lzma, base64

PAYLOAD = ''
root=Path(__file__).resolve().parents[1]
items=json.loads(lzma.decompress(base64.b64decode(PAYLOAD)))
prepared=[]
for item in items:
    rel=PurePosixPath(item['path'])
    assert not rel.is_absolute() and '..' not in rel.parts, 'Invalid path'
    target=root.joinpath(*rel.parts)
    assert target.resolve().is_relative_to(root), 'Path outside repository'
    before=hashlib.sha256(target.read_bytes()).hexdigest() if target.is_file() else None
    assert before==item['before'], 'Concurrent modification: '+item['path']
    lines=target.read_bytes().decode().splitlines(keepends=True) if target.is_file() else []
    for edit in reversed(item['edits']):
        lines[edit['start']:edit['end']]=edit['text'].splitlines(keepends=True)
    body=''.join(lines).encode()
    assert hashlib.sha256(body).hexdigest()==item['after'], 'Corrupt payload'
    prepared.append((target,body))
for target,body in prepared:
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_bytes(body)
print('Applied',len(prepared),'verified files')
